package minic.benchmark;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class StlBenchmarkProbesTest{
 @TempDir Path temp;
 @Test void countersAreParsedSeparatelyAndBalanceIsRequired(){var w=StlBenchmarkWorkloads.workloads().getFirst();var e=StlBenchmarkWorkloads.input(w,2,1,0);String hash=e.expectedStdout().strip();String fields=" comparisons=1 value_ctor=2 copy_ctor=0 move_ctor=1 copy_assign=0 move_assign=2 destroyed=3 live=0 peak_live=3 allocations=1 frees=1 allocated_bytes=8 freed_bytes=8 live_bytes=0 peak_bytes=8";assertEquals(1,StlBenchmarkProbes.validate(w,e,hash+fields+"\n").size());assertThrows(IllegalStateException.class,()->StlBenchmarkProbes.validate(w,e,hash+fields.replace("destroyed=3","destroyed=2")+"\n"));assertThrows(IllegalStateException.class,()->StlBenchmarkProbes.validate(w,e,hash+fields.replace("freed_bytes=8","freed_bytes=4")+"\n"));assertThrows(IllegalStateException.class,()->StlBenchmarkProbes.validate(w,e,hash.replace("hash=","hash=1")+fields+"\n"));}
 @Test void instrumentationCopiesExactHeadersAndNeverMutatesOriginals()throws Exception{Path original=temp.resolve("repo/lib/cpp");Files.createDirectories(original);String memory="void f(){::malloc(1);::malloc(2);::free(0);}";Files.writeString(original.resolve("memory.mh"),memory);Files.writeString(original.resolve("other.mh"),"unmodified");var result=StlBenchmarkProbes.instrumentOwnHeaders(temp.resolve("repo"),temp.resolve("copy"));assertEquals(memory,Files.readString(original.resolve("memory.mh")));assertEquals("unmodified",Files.readString(result.projectRoot().resolve("lib/cpp/other.mh")));assertTrue(Files.readString(result.projectRoot().resolve("lib/cpp/memory.mh")).contains("::bench_allocate(1)"));assertEquals(2,result.headers().size());assertNotEquals(result.headers().getFirst().originalSha256(),result.headers().getFirst().instrumentedSha256());assertThrows(FileAlreadyExistsException.class,()->StlBenchmarkProbes.instrumentOwnHeaders(temp.resolve("repo"),temp.resolve("copy")));}
 @Test void changedHookShapeFailsClosed()throws Exception{Files.createDirectories(temp.resolve("repo/lib/cpp"));Files.writeString(temp.resolve("repo/lib/cpp/memory.mh"),"no allocator here");assertThrows(IllegalStateException.class,()->StlBenchmarkProbes.instrumentOwnHeaders(temp.resolve("repo"),temp.resolve("copy")));}
}
